body.script:
(function () {
  var htmlEl = document.documentElement;
  var listBtn = document.getElementById('btn-list');
  var gridBtn = document.getElementById('btn-grid');
  var listSection = document.getElementById('list-section');
  var gridSection = document.getElementById('grid-section');
  var fsBtn = document.getElementById('fs-btn');
  var fsIcon = fsBtn ? fsBtn.querySelector('.bs2-fs-ico') : null;
  var fsText = fsBtn ? fsBtn.querySelector('.bs2-fs-tx') : null;
  var balanceUrl = htmlEl.getAttribute('data-balance-json-url') || '';
  var _balanceTimer = null;

  function asNumber(value) {
    var num = Number(value);
    return isFinite(num) ? num : 0;
  }

  function flashUpdate(element) {
    if (!element) {
      return;
    }
    element.classList.remove('bs2-flash');
    void element.offsetWidth;
    element.classList.add('bs2-flash');
    window.clearTimeout(element._flashTimer);
    element._flashTimer = window.setTimeout(function () {
      element.classList.remove('bs2-flash');
    }, 850);
  }

  function purseClass(pct) {
    if (pct >= 60) { return 'pf-high'; }
    if (pct >= 30) { return 'pf-mid'; }
    if (pct >= 10) { return 'pf-low'; }
    return 'pf-crit';
  }

  function statusMeta(pct) {
    if (pct >= 60) { return { label: 'COMFORTABLE', cls: 'comfortable' }; }
    if (pct >= 40) { return { label: 'HEALTHY', cls: 'healthy' }; }
    if (pct >= 25) { return { label: 'BALANCED', cls: 'balanced' }; }
    if (pct >= 10) { return { label: 'TIGHT', cls: 'tight' }; }
    return { label: 'CRITICAL', cls: 'critical' };
  }


  function fitMaxBidValues(scope) {
    var root = scope && scope.querySelectorAll ? scope : document;
    var nodes = root.querySelectorAll(
      '.bs2-maxbid .bs2-maxcall-value, .bs2-stat-col--maxbid .bs2-stat-figure, .bs2-mob-stat--maxbid .bs2-mob-stat-val'
    );
    Array.prototype.forEach.call(nodes, function (el) {
      var box = el.closest('.bs2-maxbid, .bs2-stat-col--maxbid, .bs2-mob-stat--maxbid');
      if (!box) { return; }
      el.style.fontSize = '';
      el.style.whiteSpace = 'nowrap';
      el.style.overflow = 'visible';
      el.style.textOverflow = 'clip';
      var pad = 16;
      var available = Math.max(40, box.clientWidth - pad);
      var size = parseFloat(window.getComputedStyle(el).fontSize) || 18;
      var minSize = 11;
      var guard = 0;
      el.style.fontSize = size + 'px';
      while (el.scrollWidth > available && size > minSize && guard < 48) {
        size -= 0.5;
        el.style.fontSize = size + 'px';
        guard += 1;
      }
    });
  }

  function maxBidHeat(maxCall, remainingPoints, remainingPlayers) {
    var share = remainingPoints > 0 ? Math.round((maxCall * 100) / remainingPoints) : 100;
    if (remainingPlayers <= 1 || share <= 15) { return 'mb-crit'; }
    if (remainingPlayers <= 3 || share <= 30) { return 'mb-tight'; }
    return 'mb-ok';
  }

  function updateMaxBidHeat(container, maxCall, remainingPoints, remainingPlayers) {
    if (!container) { return; }
    var heat = maxBidHeat(maxCall, remainingPoints, remainingPlayers);
    Array.prototype.forEach.call(container.querySelectorAll('[data-role="maxbid-callout"]'), function (el) {
      var prev = el.className;
      el.classList.remove('mb-ok', 'mb-tight', 'mb-crit');
      el.classList.add(heat);
      if (el.className !== prev) { flashUpdate(el); }
    });
  }

  function bs2Esc(s) {
    return String(s == null ? '' : s)
      .replace(/&/g, '&amp;').replace(/</g, '&lt;')
      .replace(/>/g, '&gt;').replace(/"/g, '&quot;');
  }

  function bs2FmtPts(n) {
    if (window.fmtUnit) { return window.fmtUnit(n); }
    try { return Number(n || 0).toLocaleString(); } catch (e) { return String(n || 0); }
  }

  function closeSquadModal() {
    var ov = document.getElementById('bs2-squad-overlay');
    if (ov) {
      ov.classList.remove('open');
      ov.setAttribute('aria-hidden', 'true');
    }
  }

  function closeTiersModal() {
    var ov = document.getElementById('bs2-tiers-overlay');
    if (ov) {
      ov.classList.remove('open');
      ov.setAttribute('aria-hidden', 'true');
    }
  }

  function fetchTeamPeek(teamId) {
    var base = htmlEl.getAttribute('data-squad-json-base') || '';
    if (!base || !teamId) {
      return Promise.reject(new Error('missing team'));
    }
    return fetch(base + teamId + '/squad/json', {
      method: 'GET',
      headers: { 'Accept': 'application/json' },
      cache: 'no-store'
    }).then(function (r) {
      if (!r.ok) { throw new Error('HTTP ' + r.status); }
      return r.json();
    });
  }

  function openSquadModal(teamId) {
    var ov = document.getElementById('bs2-squad-overlay');
    var body = document.getElementById('bs2-sq-body');
    var logoEl = document.getElementById('bs2-sq-hlogo');
    var nameEl = document.getElementById('bs2-sq-hname');
    var ptsEl = document.getElementById('bs2-sq-hpts');
    if (!ov || !body || !teamId) { return; }
    closeTiersModal();
    ov.classList.add('open');
    ov.setAttribute('aria-hidden', 'false');
    nameEl.textContent = 'Loading…';
    ptsEl.textContent = '';
    logoEl.innerHTML = '';
    body.innerHTML = '<div class="bs2-sq-loading">Loading squad…</div>';
    fetchTeamPeek(teamId).then(function (team) {
      nameEl.textContent = team.name || 'Team';
      ptsEl.textContent = bs2FmtPts(team.remaining_points) + ' remaining';
      logoEl.innerHTML = team.logo_url
        ? '<img src="' + bs2Esc(team.logo_url) + '" alt=""/>'
        : '&#128737;';
      var players = team.players || [];
      if (!players.length) {
        body.innerHTML = '<div class="bs2-sq-empty">No players signed yet</div>';
        return;
      }
      body.innerHTML = players.map(function (p) {
        var photo = p.photo_url
          ? '<img src="' + bs2Esc(p.photo_url) + '" alt="" onerror="this.style.display=\'none\';this.parentElement.innerHTML=\'<span class=bs2-sq-rph>&#128100;</span>\'"/>'
          : '<span class="bs2-sq-rph">&#128100;</span>';
        var meta = p.position_code || p.role || '';
        return '<div class="bs2-sq-row">' +
          '<div class="bs2-sq-rphoto">' + photo + '</div>' +
          '<div class="bs2-sq-rinfo">' +
            '<div class="bs2-sq-rname">' + bs2Esc(p.name || '—') + '</div>' +
            (meta ? '<div class="bs2-sq-rrole">' + bs2Esc(meta) + '</div>' : '') +
          '</div>' +
          '<div class="bs2-sq-rpts">' + bs2FmtPts(p.points) + '</div>' +
        '</div>';
      }).join('');
    }).catch(function () {
      body.innerHTML = '<div class="bs2-sq-empty">Could not load squad</div>';
    });
  }

  function openTiersModal(teamId) {
    var ov = document.getElementById('bs2-tiers-overlay');
    var body = document.getElementById('bs2-tr-body');
    var logoEl = document.getElementById('bs2-tr-hlogo');
    var nameEl = document.getElementById('bs2-tr-hname');
    var ptsEl = document.getElementById('bs2-tr-hpts');
    if (!ov || !body || !teamId) { return; }
    closeSquadModal();
    ov.classList.add('open');
    ov.setAttribute('aria-hidden', 'false');
    nameEl.textContent = 'Loading…';
    ptsEl.textContent = 'Tier recruitment';
    logoEl.innerHTML = '';
    body.innerHTML = '<div class="bs2-sq-loading">Loading tiers…</div>';
    fetchTeamPeek(teamId).then(function (team) {
      nameEl.textContent = team.name || 'Team';
      ptsEl.textContent = 'Tier recruitment';
      logoEl.innerHTML = team.logo_url
        ? '<img src="' + bs2Esc(team.logo_url) + '" alt=""/>'
        : '&#128737;';
      var tiers = team.tiers || [];
      if (!tiers.length) {
        body.innerHTML = '<div class="bs2-sq-empty">No tier limits configured for this team</div>';
        return;
      }
      body.innerHTML =
        '<table class="bs2-tiers-table">' +
          '<thead><tr><th>Tier</th><th class="bs2-tiers-num">Players / Max</th></tr></thead>' +
          '<tbody>' +
          tiers.map(function (t) {
            var color = t.color || '#3498db';
            var count = Number(t.count || 0);
            var max = Number(t.max || 0);
            var full = max > 0 && count >= max;
            return '<tr style="border-left:3px solid ' + bs2Esc(color) + ';">' +
              '<td><span class="bs2-tiers-name">' +
                '<span class="bs2-tiers-dot" style="background:' + bs2Esc(color) + ';box-shadow:0 0 0 3px ' + bs2Esc(color) + '33;"></span>' +
                '<span style="color:' + bs2Esc(color) + ';">' + bs2Esc(t.name || 'Tier') + '</span>' +
              '</span></td>' +
              '<td class="bs2-tiers-num">' +
                '<span class="bs2-tiers-count' + (full ? ' is-full' : '') + '" style="color:' + bs2Esc(color) + ';">' +
                  bs2Esc(String(count)) + ' / ' + bs2Esc(String(max)) +
                '</span>' +
                (full ? '<span class="bs2-tiers-full" style="color:' + bs2Esc(color) + ';">Full</span>' : '') +
              '</td>' +
            '</tr>';
          }).join('') +
          '</tbody></table>';
    }).catch(function () {
      body.innerHTML = '<div class="bs2-sq-empty">Could not load tiers</div>';
    });
  }



  function isCompactScreen() {
    return window.matchMedia('(max-width: 768px)').matches;
  }

  function setView(mode) {
    if (isCompactScreen()) {
      mode = 'grid';
    }
    var isList = mode === 'list';
    if (listSection) { listSection.style.display = isList ? '' : 'none'; }
    if (gridSection) { gridSection.style.display = isList ? 'none' : ''; }
    if (listBtn) {
      listBtn.classList.toggle('active', isList);
      listBtn.setAttribute('aria-pressed', isList ? 'true' : 'false');
    }
    if (gridBtn) {
      gridBtn.classList.toggle('active', !isList);
      gridBtn.setAttribute('aria-pressed', isList ? 'false' : 'true');
    }
  }

  function syncFullscreenButton() {
    var active = !!document.fullscreenElement;
    if (fsIcon) { fsIcon.textContent = active ? '✕' : '⛶'; }
    if (fsText) { fsText.textContent = active ? 'EXIT' : 'FULL'; }
    if (fsBtn) { fsBtn.setAttribute('aria-label', active ? 'Exit fullscreen' : 'Enter fullscreen'); }
  }

  function updateValueById(id, value) {
    var element = document.getElementById(id);
    var nextText = String(value);
      if (window.fmtUnit && /(points|maxcall)/i.test(id || '')) {
        nextText = window.fmtUnit(value);
      }
    if (!element) {
      return;
    }
    if (element.textContent.trim() !== nextText) {
      element.textContent = nextText;
      flashUpdate(element);
    }
  }

  function updateContainer(container, remainingPoints, remainingPlayers, totalPoints, maxPlayers) {
    if (!container) {
      return;
    }
    var pct = totalPoints ? Math.max(0, Math.min(100, Math.round((remainingPoints * 100) / totalPoints))) : 0;
    var recruited = Math.max(0, maxPlayers - remainingPlayers);
    var status = statusMeta(pct);

    Array.prototype.forEach.call(container.querySelectorAll('[data-role="purse-fill"]'), function (fill) {
      var nextClass = 'bs2-progress-fill ' + purseClass(pct);
      var nextWidth = pct + '%';
      if (fill.className !== nextClass) {
        fill.className = nextClass;
        flashUpdate(fill);
      }
      if (fill.style.width !== nextWidth) {
        fill.style.width = nextWidth;
        flashUpdate(fill.parentElement || fill);
      }
    });

    Array.prototype.forEach.call(container.querySelectorAll('[data-role="pct-label"]'), function (label) {
      var nextText = pct + '% remaining';
      if (label.textContent.trim() !== nextText) {
        label.textContent = nextText;
        flashUpdate(label);
      }
    });

    Array.prototype.forEach.call(container.querySelectorAll('[data-role="status-badge"]'), function (badge) {
      var nextClass = (badge.getAttribute('data-base-class') || 'bs2-badge') + ' ' + status.cls;
      if (badge.className !== nextClass) {
        badge.className = nextClass;
        flashUpdate(badge);
      }
      if (badge.textContent.trim() !== status.label) {
        badge.textContent = status.label;
        flashUpdate(badge);
      }
    });

    Array.prototype.forEach.call(container.querySelectorAll('[data-role="squad-value"]'), function (squad) {
      var nextText = recruited + ' / ' + maxPlayers;
      if (squad.textContent.trim() !== nextText) {
        squad.textContent = nextText;
        flashUpdate(squad);
      }
    });
  }

  function normalizePayload(payload) {
    function objectMap(source) {
      return Object.keys(source || {}).map(function (key) {
        var item = source[key];
        if (item === null || typeof item !== 'object' || Array.isArray(item)) {
          item = { remaining_points: item };
        }
        if (item.id === undefined && item.auction_id === undefined) {
          item.id = key;
        }
        return item;
      });
    }

    if (!payload) { return []; }
    if (Array.isArray(payload)) { return payload; }
    if (Array.isArray(payload.teams)) { return payload.teams; }
    if (Array.isArray(payload.data)) { return payload.data; }
    if (Array.isArray(payload.results)) { return payload.results; }
    if (payload.teams && typeof payload.teams === 'object') { return objectMap(payload.teams); }
    if (payload.data && typeof payload.data === 'object') { return objectMap(payload.data); }
    if (payload.results && typeof payload.results === 'object') { return objectMap(payload.results); }
    if (typeof payload === 'object') { return objectMap(payload); }
    return [];
  }

  function resolveAuctionId(entry) {
    if (!entry || typeof entry !== 'object') {
      return 0;
    }
    if (entry.id !== undefined) { return asNumber(entry.id); }
    if (entry.auction_id !== undefined) { return asNumber(entry.auction_id); }
    if (entry.auctionId !== undefined) { return asNumber(entry.auctionId); }
    if (entry.team_id && typeof entry.team_id === 'object' && entry.team_id.id !== undefined) {
      return asNumber(entry.team_id.id);
    }
    if (entry.team_id !== undefined) { return asNumber(entry.team_id); }
    return 0;
  }

  function applyBalancePayload(payload) {
      if (window.__acTrackerOnBalance) {
        try { window.__acTrackerOnBalance(payload); } catch (e0) {}
      }
      normalizePayload(payload).forEach(function (entry) {
        var auctionId = resolveAuctionId(entry);
        if (!auctionId) {
          return;
        }
        var row = document.querySelector('tr[data-auction-id="' + auctionId + '"]');
        var card = document.querySelector('.bs2-card[data-auction-id="' + auctionId + '"]');
        var totalPoints = asNumber(
          entry.total_point !== undefined ? entry.total_point :
          entry.total_points !== undefined ? entry.total_points :
          entry.totalPts !== undefined ? entry.totalPts :
          (row ? row.getAttribute('data-total-pts') : null) ||
          (card ? card.getAttribute('data-total-pts') : null)
        );
        var maxPlayers = asNumber(
          entry.max_players !== undefined ? entry.max_players :
          entry.maxPlayers !== undefined ? entry.maxPlayers :
          (row ? row.getAttribute('data-max-players') : null) ||
          (card ? card.getAttribute('data-max-players') : null)
        );
        var remainingPoints = asNumber(
          entry.remaining_points !== undefined ? entry.remaining_points :
          entry.remainingPoints !== undefined ? entry.remainingPoints :
          entry.points !== undefined ? entry.points :
          entry.purse_remaining !== undefined ? entry.purse_remaining :
          entry.balance !== undefined ? entry.balance : 0
        );
        var remainingPlayers = asNumber(
          entry.remaining_players_count !== undefined ? entry.remaining_players_count :
          entry.remainingPlayersCount !== undefined ? entry.remainingPlayersCount :
          entry.players_needed !== undefined ? entry.players_needed :
          entry.playersNeeded !== undefined ? entry.playersNeeded :
          entry.remaining_players !== undefined ? entry.remaining_players : 0
        );
        var maxCall = asNumber(
          entry.max_call !== undefined ? entry.max_call :
          entry.maxCall !== undefined ? entry.maxCall :
          entry.max_bid !== undefined ? entry.max_bid :
          entry.maxBid !== undefined ? entry.maxBid :
          entry.maxcall !== undefined ? entry.maxcall : 0
        );

        updateValueById('team-points-' + auctionId, remainingPoints);
        updateValueById('team-players-' + auctionId, remainingPlayers);
        updateValueById('team-maxcall-' + auctionId, maxCall);
        updateValueById('grid-team-points-' + auctionId, remainingPoints);
        updateValueById('grid-team-players-' + auctionId, remainingPlayers);
        updateValueById('grid-team-maxcall-' + auctionId, maxCall);

        updateContainer(row, remainingPoints, remainingPlayers, totalPoints, maxPlayers);
        updateContainer(card, remainingPoints, remainingPlayers, totalPoints, maxPlayers);
        updateMaxBidHeat(row, maxCall, remainingPoints, remainingPlayers);
        updateMaxBidHeat(card, maxCall, remainingPoints, remainingPlayers);
        fitMaxBidValues(row);
        fitMaxBidValues(card);
      });
  }

  function refreshBalance() {
    if (!balanceUrl) {
      return Promise.resolve();
    }
    return fetch(balanceUrl, {
      method: 'GET',
      headers: { 'Accept': 'application/json' },
      cache: 'no-store'
    }).then(function (response) {
      if (!response.ok) {
        throw new Error('HTTP ' + response.status);
      }
      return response.json();
    }).then(function (payload) {
      applyBalancePayload(payload);
    }).catch(function () {
      return null;
    });
  }

  window.refreshBalance = refreshBalance;
  window.__acApplyBalance = applyBalancePayload;

  document.addEventListener('click', function (e) {
    var eye = e.target && e.target.closest ? e.target.closest('.bs2-eye-btn') : null;
    if (eye) {
      e.preventDefault();
      openSquadModal(eye.getAttribute('data-team-id'));
      return;
    }
    var tiersBtn = e.target && e.target.closest ? e.target.closest('.bs2-tiers-btn') : null;
    if (tiersBtn) {
      e.preventDefault();
      openTiersModal(tiersBtn.getAttribute('data-team-id'));
      return;
    }
    if (e.target && (e.target.id === 'bs2-sq-hclose' || e.target.id === 'bs2-squad-overlay')) {
      closeSquadModal();
    }
    if (e.target && (e.target.id === 'bs2-tr-hclose' || e.target.id === 'bs2-tiers-overlay')) {
      closeTiersModal();
    }
  });
  document.addEventListener('keydown', function (e) {
    if (e.key === 'Escape') {
      closeSquadModal();
      closeTiersModal();
    }
  });


  function stopPolling() {
    if (_balanceTimer) {
      clearInterval(_balanceTimer);
      _balanceTimer = null;
    }
  }

  function startPolling() {
    stopPolling();
    _balanceTimer = setInterval(refreshBalance, 8000);
  }

  if (listBtn) {
    listBtn.addEventListener('click', function () { setView('list'); });
  }
  if (gridBtn) {
    gridBtn.addEventListener('click', function () { setView('grid'); });
  }
  if (fsBtn) {
    fsBtn.addEventListener('click', function () {
      if (document.fullscreenElement) {
        if (document.exitFullscreen) {
          document.exitFullscreen();
        }
      } else if (htmlEl.requestFullscreen) {
        htmlEl.requestFullscreen();
      }
    });
  }

  document.addEventListener('fullscreenchange', syncFullscreenButton);
  document.addEventListener('visibilitychange', function () {
    if (document.hidden) {
      stopPolling();
    } else {
      refreshBalance();
      startPolling();
    }
  });
  fitMaxBidValues();
  window.addEventListener('resize', function () {
    window.clearTimeout(window._bs2FitMb);
    window._bs2FitMb = window.setTimeout(function () { fitMaxBidValues(); }, 120);
  });
  window.addEventListener('beforeunload', stopPolling);
  document.addEventListener('DOMContentLoaded', function () {
    setView(isCompactScreen() ? 'grid' : 'list');
    syncFullscreenButton();
    if (window.AuctionChampSSE && window.AuctionChampSSE.enabled(document.documentElement)) {
      window.AuctionChampSSE.bind({
        url: document.documentElement.getAttribute('data-sse-url'),
        apply: applyBalancePayload,
        startPoll: function () { refreshBalance(); startPolling(); },
        stopPoll: stopPolling,
      });
    } else {
      refreshBalance();
      if (!document.hidden) {
        startPolling();
      }
    }
  });
  if (window.matchMedia) {
    var compactMq = window.matchMedia('(max-width: 768px)');
    var onCompactChange = function () {
      setView(isCompactScreen() ? 'grid' : (listBtn && listBtn.classList.contains('active') ? 'list' : 'grid'));
    };
    if (compactMq.addEventListener) compactMq.addEventListener('change', onCompactChange);
    else if (compactMq.addListener) compactMq.addListener(onCompactChange);
  }
}());
